def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip().lower()

        # Use the portion inside angle brackets when present.
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1).strip()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return local + "@" + domain

    def normalize_phone(value):
        extension = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if extension:
            value = value[:extension.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for index, row in enumerate(rows):
        item = {
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
        }

        # Rows without either valid contact identifier cannot participate.
        if item["email"] or item["phone"]:
            normalized.append(item)

    count = len(normalized)
    parent = list(range(count))
    rank = [0] * count

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return

        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a
        parent[root_b] = root_a

        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for position, item in enumerate(normalized):
        if item["email"]:
            previous = email_owner.get(item["email"])
            if previous is None:
                email_owner[item["email"]] = position
            else:
                union(position, previous)

        last_name_key = item["last_name"].casefold()
        if item["phone"] and last_name_key:
            key = (item["phone"], last_name_key)
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = position
            else:
                union(position, previous)

    groups = {}
    for position, item in enumerate(normalized):
        groups.setdefault(find(position), []).append(item)

    def select_field(group, field):
        candidates = [item for item in group if item[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda item: (
                item["source"] == "manual",
                item["updated_dt"],
                -item["index"],
            ),
        )
        return best[field]

    output = []

    for group in sorted(groups.values(), key=lambda g: min(x["index"] for x in g)):
        latest = max(item["updated_dt"] for item in group)
        tags = set()

        for item in group:
            tags.update(item["tags"])

        output.append(
            {
                "first_name": select_field(group, "first_name"),
                "last_name": select_field(group, "last_name"),
                "zip": select_field(group, "zip"),
                "email": select_field(group, "email"),
                "phone": select_field(group, "phone"),
                "source": select_field(group, "source"),
                "tags": ";".join(sorted(tags)),
                "opted_out": (
                    "Y" if any(item["opted_out"] for item in group) else "N"
                ),
                "updated": latest.strftime("%Y-%m-%d"),
            }
        )

    return output
